import AgileCLU
import unittest

class AgileCLUTestCase(unittest.TestCase):
  def setup(self):
    self.agileclu = AgileCLU()
  def test_epwbasekey(self):
    vrn_key = self.agileclu.e_pw_dehash("4WE50Nxefa3Hrt833Ygxv1K0rO0S5HD3RHc6+I5WDP3p3KNUU+epFGXOFGjeIDOpxr1q0IWEd32AGTDbIg==")
    self.assertEqual("sitepassword", vrn_key)

  def test_e_pw_hash(self):
    key_hash = self.agileclu.e_pw_hash("4WE50Nxefa3Hrt833Ygxv1K0rO0S5HD3RHc6+I5WDP3p3KNUU+epFGXOFGjeIDOpxr1q0IWEd32AGTDbIg==")
    self.assertEqual("test", key_hash)

  def test_e_pw_dehash(self):
    key_hash = self.agileclu.e_pw_dehash("4WE50Nxefa3Hrt833Ygxv1K0rO0S5HD3RHc6+I5WDP3p3KNUU+epFGXOFGjeIDOpxr1q0IWEd32AGTDbIg==")
