import AgileCLU
import unittest
import hashlib
from os import urandom

class AgileCLUTestCase(unittest.TestCase):
  def setup(self):
    self.agileclu = AgileCLU()
  def test_epwbasekey(self):
    return
  def test_e_pw_hash(self):
    salt = urandom(32)
    hashed = self.agileclu.e_pw_hash("test", salt)
    self.assertEqual("", hashlib.sha512(bytes([somebyte ^ bytediff for somebyte, bytediff in zip(salt, hashed)])).hexdigest())
  def test_e_pw_dehash(self):
    salt = urandom(32)
    hashed = self.agileclu.e_pw_hash("test", salt)
    self.assertEqual("test", self.agileclu.e_pw_dehash(hashed, salt))

if __name__ == "__main__":
  unittest.main()

