#!/usr/bin/env python

import AgileCLU
import unittest

class AgileCLUTestCase(unittest.TestCase):
  def setup(self):
    self.agileclu = AgileCLU()
  def test_epwbasekey(self):
    return
  def test_e_pw_hash(self):
    hashed = self.agileclu.e_pw_hash("password")
    self.assertTrue(hashed is not None)
    self.assertTrue(len(hashed) == 64, "64 chars long." )
    self.assertTrue(isinstance(hashed, str))

    hashed2 = self.agileclu.e_pw_hash("password")
    self.assertTrue(hashed != hashed2, "with differing salts.")

    self.assertTrue(self.agileclu.e_pw_dehash("confidence", hashed) is True)
    self.assertTrue(self.agileclu.e_pw_dehash("password", hashed) is False)

if __name__ == "__main__":
  unittest.main()

